#include<bits/stdc++.h>
using namespace std;
#define MAX 2005

int walk[4][2]={{1,0},{-1,0},{0,1},{0,-1}};
int n,m,k;
char s[MAX];
int nums[MAX][MAX],d[MAX][MAX];
struct coord{
    int x,y;
};
queue<coord>Q;

int main()
{
    memset(d,-1,sizeof(d));
    cin>>n>>m>>k;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            cin>>s[j];
            if(s[j]=='X')
                nums[i][j]=0;
            else
                nums[i][j]=1;
        }
    }
    Q.push({1,1});
    d[1][1]=0;
    while(!Q.empty()){
        coord u=Q.front();
        int ux=u.x,uy=u.y;
        if(ux==n&&uy==m)
            break;
        Q.pop();
        for(int i=0;i<4;i++){
            int x=ux+walk[i][0],y=uy+walk[i][1];
            if(x==0||y==0||x>n||y>m||d[x][y]!=-1||nums[x][y]==0)
                continue;
            d[x][y]=d[ux][uy];
            if(i==1||i==3)
                d[x][y]++;
            Q.push({x,y});
        }
    }
    long long time[k+1],a[k+1],b[k+1],ans=1e18;
    int cnt=0;
    for(int i=1;i<=k;i++){
        cin>>a[i]>>b[i];
        time[i]=a[i]*(n+m-2+d[n][m])+b[i]*d[n][m];
        ans=min(ans,time[i]);
    }
    for(int i=1;i<=k;i++){
        if(time[i]==ans)
            cnt++;
    }
    printf("%lld %d\n",ans,cnt);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 6005;
const int INF = 1e18;

int n,m;
int val[MAXN];
int need[MAXN];//表示来到这个节点为首的子树上 最低有多少个苹果就可以赚钱

int cnt=1;
int head[MAXN];
int nxt[MAXN];
int to[MAXN];

struct node{
    int need,id;
};
struct cmp{
    bool operator()(node a,node b){
        return a.need>b.need;
    }
};
priority_queue<node,vector<node>,cmp>q;

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

inline void clear(){
    while(!q.empty()){
        q.pop();
    }
}

inline void dfs(int u){
    clear();
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v);
    }
    if(val[u]>=0){
        //如果这个位置是苹果  那么肯定直接就是赚钱的
        need[u]=0;
        return ;
    }
    clear();
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        q.push({need[v],v});//所有子节点入队
    }
    need[u]-=val[u];//这是目前的最低花费
    bool flag=false;
    int tot=0;//这是目前拥有的苹果数量
    while(!q.empty()){
        if(tot-need[u]>=0){
            //表示苹果已经比需要的多了 那么就是赚了
            flag=true;
            break;
        }
        node x=q.top();
        q.pop();
        if(tot<need[x.id]){
            //表示现在有的苹果数量无法进入这个子树赚钱
            need[u]+=need[x.id]-tot;//那么至少要进入这个子树赚钱  因为这已经是最容易的了
            tot=need[x.id];//将拥有的苹果数量变为此时的要求
        }
        tot+=val[x.id];
        for(int i=head[x.id];i;i=nxt[i]){
            int v=to[i];
            q.push({need[v],v});
        }
    }
    if(tot-need[u]>=0){
        flag=true;
    }
    if(!flag){
        need[u]=INF;
    }
}

signed main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin>>n>>m;
    for(int i=2;i<=n;i++){
        int u;
        cin>>u;
        addedge(u,i);
    }
    for(int i=1;i<=n;i++){
        cin>>val[i];
    }
    dfs(1);
    clear();
    q.push({need[1],1});
    int ans=m;
    while(!q.empty()){
        node x=q.top();
        q.pop();
        if(ans<need[x.id]){
            break;
        }
        ans+=val[x.id];
        for(int i=head[x.id];i;i=nxt[i]){
            int v=to[i];
            q.push({need[v],v});
        }
    }
    cout<<ans<<endl;
    return 0;
}

// https://www.luogu.com.cn/problem/P5829
#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;
const int LIMIT = 22;

int n,p;
int Next[MAXN];
char s[MAXN];

int head[MAXN];
int nxt[MAXN];
int to[MAXN];
int cnt=1;

int dep[MAXN];
int st[MAXN][LIMIT];

// 计算1-based next数组
void calcnext(){
    Next[1]=0;
    for(int i=2,j=0;i<=n;i++){
        // 当不匹配时，通过next数组回溯
        while(j>0&&s[i]!=s[j+1]){
            j=Next[j];
        }
        // 如果当前字符匹配，j增加
        if(s[i]==s[j+1]){
            j++;
        }
        // 设置当前位置的next值
        Next[i]=j;
    }
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        dfs(v,u);
    }
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        //如果相同说明就是祖先关系
        //那么还要向上跳一下  因为要求的是border
        //实际上也可以求stjump[u][0],stjump[v][0]的lca  这样不用跳  直接就是lca
        return st[a][0];
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int main()
{
    scanf("%s",s+1);
    n=strlen(s+1);
    p=log2(n+1)+1;
    calcnext();
    for(int i=1;i<=n;i++){
        addedge(Next[i],i);
        // cout<<Next[i]<<":   "<<i<<endl;
    }
    dfs(0,0);
    int T;
    cin>>T;
    while(T--){
        int u,v;
        cin>>u>>v;
        cout<<lca(u,v)<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e5+5;
const int MAXB = 25;

int T,n,m,maxv;
int a[MAXN];
int b[MAXN];

int bcnt;
int belong[MAXN];
int bl[MAXB];
int br[MAXB];
int mode[MAXB];

long long cnt[MAXB][MAXN];
long long tmp[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9')
    {
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void write(int x){
    if(x<0)
        putchar('-'),x=-x;
    if(x>9)
        write(x/10);
    putchar(x%10+'0');
    return;
}

void build(){
    int r=n;
    int len=1;

    while(r>=1){
        ++bcnt;
        bl[bcnt]=max(1,r-len+1);
        br[bcnt]=r;
        for(int i=bl[bcnt];i<=br[bcnt];i++){
            belong[i]=bcnt;
        }
        r-=len;
        len<<=1;
    }

    for(int block=bcnt;block>=1;block--){
        for(int i=0;i<=maxv;i++){
            cnt[block][i]=cnt[block+1][i];
        }
        mode[block]=mode[block+1];

        for(int i=bl[block];i<=br[block];i++){
            int val=b[i];
            cnt[block][val]+=a[i];

            int pre=mode[block];
            if((cnt[block][val]>cnt[block][pre])||((cnt[block][val]==cnt[block][pre])&&val>pre)){
                mode[block]=val;
            }
        }
    }
}

void update(int x,int y){
    a[x]+=y;
    int val=b[x];
    for(int i=belong[x];i>=1;i--){
        cnt[i][val]+=y;
        int pre=mode[i];
        if((cnt[i][val]>cnt[i][pre])||((cnt[i][val]==cnt[i][pre])&&val>pre)){
            mode[i]=val;
        }
    }
}

int query(int q){
    long long sum=0;
    for(int i=1;i<=bcnt;i++){
        int pre=mode[i+1];

        long long *now=cnt[i+1];
        for(int j=bl[i];j<=br[i];j++){
            int val=b[j];
            now[val]+=a[j];
            if((now[val]>now[pre])||((now[val]==now[pre])&&val>pre)){
                pre=val;
            }
            tmp[j]=pre*a[j];
        }
        for(int j=bl[i];j<=br[i];j++){
            int val=b[j];
            now[val]-=a[j];
        }

        for(int j=br[i];j>=bl[i];j--){
            sum^=tmp[j];
            if(sum==q){
                return n-j+1;
            }
        }
    }
    return n;
}

int main()
{
    T=read();
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        a[i]=read();
        b[i]=read();
        maxv=max(maxv,b[i]);
    }

    build();

    while(m--){
        int op=read();
        if(op==1){
            int x,y;
            x=read(),y=read();
            update(x,y);
        }
        else{
            int p=read();
            int ans=query(p);
            write(ans);
            putchar('\n');
        }
    }
    return 0;
}

// P3679 [CERC2016] 二分毯 Bipartite Blanket
// 核心结论：点集 V = S ∪ T (S⊆A, T⊆B) 能被匹配覆盖 ⇔ S 和 T 各自都能被匹配覆盖
// 步骤：
//   1. 用霍尔定理 + SOS DP 找出 A、B 两侧所有"可匹配"的子集
//   2. 收集它们的权值
//   3. 排序后双指针统计 wa + wb ≥ t 的对数

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> adjA(n, 0), adjB(m, 0);
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < m; ++j) {
            if (s[j] == '1') {
                adjA[i] |= (1 << j);
                adjB[j] |= (1 << i);
            }
        }
    }

    vector<long long> valA(n), valB(m);
    for (int i = 0; i < n; ++i) cin >> valA[i];
    for (int j = 0; j < m; ++j) cin >> valB[j];

    long long t;
    cin >> t;

    // ------- A 侧：找出所有可匹配的子集 -------
    int szA = 1 << n;
    vector<int> neiA(szA, 0), fA(szA, 0);      // fA[mask] = |mask| - |N(mask)|
    vector<long long> sumA(szA, 0);
    vector<long long> wtA;                      // 可匹配子集的权值

    for (int mask = 1; mask < szA; ++mask) {
        int lb = mask & -mask;
        int i = __builtin_ctz(lb);
        int prev = mask ^ lb;
        neiA[mask] = neiA[prev] | adjA[i];
        sumA[mask] = sumA[prev] + valA[i];
        fA[mask] = __builtin_popcount(mask) - __builtin_popcount(neiA[mask]);
    }

    // SOS DP：gA[mask] = max over submask ⊆ mask of fA[submask]
    vector<int> gA = fA;
    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < szA; ++mask) {
            if (mask >> i & 1) {
                gA[mask] = max(gA[mask], gA[mask ^ (1 << i)]);
            }
        }
    }

    for (int mask = 0; mask < szA; ++mask) {
        if (gA[mask] <= 0) wtA.push_back(sumA[mask]);
    }

    // ------- B 侧同理 -------
    int szB = 1 << m;
    vector<int> neiB(szB, 0), fB(szB, 0);
    vector<long long> sumB(szB, 0);
    vector<long long> wtB;

    for (int mask = 1; mask < szB; ++mask) {
        int lb = mask & -mask;
        int i = __builtin_ctz(lb);
        int prev = mask ^ lb;
        neiB[mask] = neiB[prev] | adjB[i];
        sumB[mask] = sumB[prev] + valB[i];
        fB[mask] = __builtin_popcount(mask) - __builtin_popcount(neiB[mask]);
    }

    vector<int> gB = fB;
    for (int i = 0; i < m; ++i) {
        for (int mask = 0; mask < szB; ++mask) {
            if (mask >> i & 1) {
                gB[mask] = max(gB[mask], gB[mask ^ (1 << i)]);
            }
        }
    }

    for (int mask = 0; mask < szB; ++mask) {
        if (gB[mask] <= 0) wtB.push_back(sumB[mask]);
    }

    // ------- 双指针统计 -------
    sort(wtA.begin(), wtA.end());
    sort(wtB.begin(), wtB.end());

    long long ans = 0;
    int j = (int)wtB.size() - 1;
    for (long long wa : wtA) {
        while (j >= 0 && wa + wtB[j] >= t) --j;
        ans += wtB.size() - 1 - j;
    }

    cout << ans << '\n';
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;
const int INF = 1e9;

int n;
int col[MAXN];

int cnt=1;
int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];

int dp[MAXN][2][2];
int f[MAXN][2][2];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

void dfs(int u,int fa){
    int flag=0;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs(v,u);
        flag++;
        for(int a=0;a<2;a++){
            for(int b=0;b<2;b++){
                f[u][a][b]=INF;
            }
        }
        if(flag==1){
            f[u][0][1]=dp[v][0][1];
            f[u][1][1]=dp[v][1][1];
            f[u][1][0]=dp[v][1][0];
            f[u][0][0]=dp[v][0][0];
        }
        else{
            for(int a=0;a<2;a++){
                for(int b=0;b<2;b++){
                    for(int c=0;c<2;c++){
                        f[u][a][b^c]=min(f[u][a][b^c],dp[u][a][b]+dp[v][a][c]);
                    }
                }
            }
        }
        for(int a=0;a<2;a++){
            for(int b=0;b<2;b++){
                dp[u][a][b]=f[u][a][b];
            }
        }
    }
    if(flag==0){
        dp[u][col[u]][0]=0;
        dp[u][col[u]^1][1]=1;
        dp[u][col[u]][1]=2;
        dp[u][col[u]^1][0]=1;
        return ;
    }
    dp[u][0][1]=dp[u][0][0]=dp[u][1][0]=dp[u][1][1]=INF;
    dp[u][col[u]][0]=min(f[u][col[u]][0],f[u][col[u]][1]+1);
    dp[u][col[u]^1][1]=min(f[u][col[u]^1][1],f[u][col[u]^1][0]+1);
    dp[u][col[u]][1]=dp[u][col[u]^1][1]+1;
    dp[u][col[u]^1][0]=dp[u][col[u]][0]+1;
}

