        addedge(i,u,w);
        addedge(u,i,w);
    }
    int ans=0;
    for(int i=1;i<=n;i++){
        if(dfn[i]==0){
            ans+=compute(i);
        }
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e6+5;
const int MAXM = MAXN << 1; // 扩展为两倍大小

int n, k;
int nums[MAXN];
int lastpos[MAXN];
long long val[MAXM]; // 注意：val需要两倍空间
long long eorval[MAXN];
long long sum[MAXM]; // 前缀和数组
long long arr[MAXM]; // 离散化数组

vector<int> vec[MAXN]; // 使用MAXM大小
int pos[MAXN]; // 第一问指针
int nxtpos[MAXN]; // 第二问指针

mt19937_64 rng(time(0)); // 64位随机数生成器

inline int read() {
    int x = 0, f = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x * f;
}

int find(long long val, int m) {
    int l = 1, r = m, ans = 0;
    while (l <= r) {
        int mid = (l + r) >> 1;
        if (arr[mid] >= val) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

int calc(int cut, int r) {
    return abs(2 * (r - cut) - n); // 简化距离计算公式
}

int main() {
    n = read(), k = read();
    int dis = (n + 1) / 2; // 循环移位中点到右端点的距离
    for (int i = 1; i <= n; i++) {
        nums[i] = read();
        lastpos[nums[i]] = i;
    }

    // 生成随机权值并计算前缀和
    for (int i = 1; i <= n; i++) {
        if (lastpos[nums[i]] == i) {
            val[i] = eorval[nums[i]];
        } else {
            val[i] = rng();
            eorval[nums[i]] ^= val[i];
        }
    }
    for (int i = n + 1; i <= 2 * n; i++) {
        val[i] = val[i - n]; // 复制一份
    }
    for (int i = 1; i <= 2 * n; i++) {
        sum[i] = sum[i - 1] ^ val[i];
        arr[i] = sum[i]; // 复制到离散化数组
    }

    // 离散化
    sort(arr + 1, arr + 2 * n + 1);
    int m = unique(arr + 1, arr + 2 * n + 1) - arr - 1;
    for (int i = 1; i <= 2 * n; i++) {
        sum[i] = find(sum[i], m); // 获取离散化后的值
    }

    // 初始化vec：存储1~n的位置
    for (int i = 1; i <= n; i++) {
        vec[sum[i]].push_back(i);
    }

    long long ans = 0;
    int minans = n;
    for (int i = n + 1; i <= 2 * n; i++) {
        int w = sum[i];
        // 更新第一问指针：跳过超出[i-n, i]区间的位置
        while (pos[w] < (int)vec[w].size() && vec[w][pos[w]] <= i - n) {
            pos[w]++;
        }
        ans += vec[w].size() - pos[w]; // 统计合法对数

        // 更新第二问指针：确保在有效范围内
        nxtpos[w] = max(nxtpos[w], pos[w]);
        while (nxtpos[w] < (int)vec[w].size() - 1 && 
               vec[w][nxtpos[w] + 1] <= i - dis) {
            nxtpos[w]++;
        }

        // 用最近的两个位置更新最小距离
        minans = min(minans, calc(vec[w][nxtpos[w]], i));
        if (nxtpos[w] + 1 < (int)vec[w].size()) {
            minans = min(minans, calc(vec[w][nxtpos[w] + 1], i));
        }

        // 将当前位置加入vec
        vec[w].push_back(i);
    }

    printf("%lld %d\n", ans / 2, minans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 20130427;
const int MAXN = 1e5+5;

int ans;
int len,k;
int nums[MAXN];

int sum[MAXN];
int sumcnt[MAXN][2];
int sumval[MAXN][2];
int sumsuf[MAXN][2];
int sumlen[MAXN][2];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

int compute(){
    if(len==1&&nums[1]==0){
        return 0;
    }
    int s=0,q=0,l=0;
    for(int i=len;i>=1;i--){
        s=(k*s+(l+1)*nums[i])%MOD;
        q=(q+s)%MOD;
        l=l+1;
    }
    return q%MOD;
}

int solve(){
    memset(sumcnt,0,sizeof(sumcnt));
    memset(sumval,0,sizeof(sumval));
    memset(sumsuf,0,sizeof(sumsuf));
    memset(sumlen,0,sizeof(sumlen));

    sumcnt[len+1][0]=1;
    for(int i=len;i>=1;i--){
        int c=(i==len)?0:k;//这个就仅仅只是针对最高位的  类似于一个特判形式
        // 每个公式的c-1表示的是前面什么都没有  从这里开始填数字的  但是一定不是0  否则不就是前导0吗

        sumcnt[i][0]=sumcnt[i+1][0];
        sumcnt[i][1]=((c-1)+(sumcnt[i+1][1]*k%MOD)+(sumcnt[i+1][0]*nums[i]%MOD))%MOD;

        sumlen[i][0]=(sumlen[i+1][0]+sumcnt[i+1][0])%MOD;
        sumlen[i][1]=((c-1)+(sumlen[i][0]*nums[i]%MOD)+((sumlen[i+1][1]+sumcnt[i+1][1])*k%MOD))%MOD;

        sumsuf[i][0]=((sumsuf[i+1][0]*k%MOD)+(sumlen[i][0]*nums[i]%MOD))%MOD;
        sumsuf[i][1]=(sum[c]+((sumsuf[i+1][0]*k%MOD)*nums[i])%MOD+
                      (sum[nums[i]]*sumlen[i][0]%MOD)+(sumsuf[i+1][1]*k%MOD*k%MOD)
                     +(sum[k]*(sumlen[i+1][1]+sumcnt[i+1][1])%MOD))%MOD;

        sumval[i][0]=(sumval[i+1][0]+sumsuf[i][0])%MOD;
        sumval[i][1]=((sumval[i+1][0]*nums[i])%MOD+(sumval[i+1][1]*k)%MOD+sumsuf[i][1])%MOD;
    }

    return (sumval[1][0]+sumval[1][1])%MOD;
} 

signed main()
{
    k=read(),len=read();
    sum[0]=0;
    for(int i=0;i<k;i++){
        sum[i+1]=(sum[i]+i)%MOD;
    }
    for(int i=1;i<=len;i++){
        nums[len-i+1]=read();
    }
    ans=compute();
    ans=(ans-solve()+MOD)%MOD;

    len=read();
    for(int i=1;i<=len;i++){
        nums[len-i+1]=read();
    }
    ans=(ans+solve())%MOD;
    ans=(ans%MOD+MOD)%MOD;
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;
const int MAXM = 1e5+5;
const int MAXB = 405;

int n,m;
int val[MAXN];
long long presum[MAXN];

int blen,bnum;
int bi[MAXN];
int bl[MAXB];
int br[MAXB];

struct node{
    int l,r,id;
};
node nums[MAXN];

int headql[MAXN];
int headqr[MAXN];
int nxtq[MAXN<<1];
int ql[MAXN<<1];
int qr[MAXN<<1];
int qop[MAXN<<1];
int qid[MAXN<<1];
int cntq=1;

long long treecnt[MAXM];
long long treesum[MAXM];
long long pre[MAXN];
long long suf[MAXN];

int blocklesscnt[MAXB];
int numlesscnt[MAXM];
long long blockmoresum[MAXB];
long long nummoresum[MAXM];

long long ans[MAXN];

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

bool cmp(node &a, node &b) {
    if (bi[a.l] != bi[b.l]) {
        return bi[a.l] < bi[b.l];
    }
    if ((bi[a.l] & 1) == 1) {
        return a.r < b.r;
    } else {
        return a.r > b.r;
    }
}

void prepare(){
    for(int i=1;i<=n;i++){
        presum[i]=presum[i-1]+val[i];
    }

    blen=sqrt(MAXM-1);
    bnum=(MAXM+blen-2)/blen;
    for(int i=1;i<MAXM;i++){
        bi[i]=(i-1)/blen+1;
    }
    for(int i=1;i<=bnum;i++){
        bl[i]=(i-1)*blen+1;
        br[i]=min(MAXM-1,i*blen);
    }

    sort(nums+1,nums+m+1,cmp);
}

inline int lowbit(int x){
    return x&-x;
}

void add(long long *tree,int x,int v){
    while(x<MAXM){
        tree[x]+=v;
        x+=lowbit(x);
    }
}

long long sum(long long *tree,int x){
    long long ans=0;
    while(x){
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}

void addleftoffline(int x,int l,int r,int op,int id){
    nxtq[cntq]=headql[x];
    ql[cntq]=l;
    qr[cntq]=r;
    qop[cntq]=op;
    qid[cntq]=id;
    headql[x]=cntq++;
}

void addrightoffline(int x,int l,int r,int op,int id){
    nxtq[cntq]=headqr[x];
    ql[cntq]=l;
    qr[cntq]=r;
    qop[cntq]=op;
    qid[cntq]=id;
    headqr[x]=cntq++;
}

void addval(int val){
    for(int b=bi[val]+1;b<=bi[MAXM-1];b++){
        blocklesscnt[b]++;
    }
    for(int i=val+1;i<=br[bi[val]];i++){
        numlesscnt[i]++;
    }
    for(int b=1;b<=bi[val]-1;b++){
        blockmoresum[b]+=val;
    }
    for(int i=bl[bi[val]];i<val;i++){
        nummoresum[i]+=val;
    }
}

int lesscnt(int x){
    return blocklesscnt[bi[x]]+numlesscnt[x];
}

long long moresum(int x){
    return blockmoresum[bi[x]]+nummoresum[x];
}

void compute(){
    for(int i=1;i<=n;i++){
        pre[i]=pre[i-1]+(1ll*val[i]*sum(treecnt,val[i]-1))+(presum[i-1]-sum(treesum,val[i]));
        add(treecnt,val[i],1);
        add(treesum,val[i],val[i]);
    }
    for(int i=1;i<MAXM;i++){
        treecnt[i]=0;
        treesum[i]=0;
    }
    for(int i=n;i>=1;i--){
        suf[i]=suf[i+1]+(1ll*val[i]*sum(treecnt,val[i]-1))+(sum(treesum,MAXM-1)-sum(treesum,val[i]));
        add(treecnt,val[i],1);
        add(treesum,val[i],val[i]);
    }

    int winl=1,winr=0;
    for(int i=1;i<=m;i++){
        int jobl=nums[i].l;
        int jobr=nums[i].r;
        int jobi=nums[i].id;

        if(winr<jobr){
            if(winl>1){
                addleftoffline(winl-1,winr+1,jobr,-1,jobi);
            }
            ans[jobi]+=pre[jobr]-pre[winr];
        }
        if(winr>jobr){
            if(winl>1){
                addleftoffline(winl-1,jobr+1,winr,1,jobi);
            }
            ans[jobi]+=pre[jobr]-pre[winr];
        }
        winr=jobr;

        if(winl>jobl){
            if(winr<n){
                addrightoffline(winr+1,jobl,winl-1,-1,jobi);
            }
            ans[jobi]+=suf[jobl]-suf[winl];
        }
        if(winl<jobl){
            if(winr<n){
                addrightoffline(winr+1,winl,jobl-1,1,jobi);
            }
            ans[jobi]+=suf[jobl]-suf[winl];
        }
        winl=jobl;
    }

    long long tmp;
    for(int x=1;x<=n;x++){
        addval(val[x]);
        for(int i=headql[x];i;i=nxtq[i]){
            int l=ql[i],r=qr[i],op=qop[i],id=qid[i];
            for(int j=l;j<=r;j++){
                tmp=1ll*lesscnt(val[j])*val[j]+moresum(val[j]);
                if(op==1){
                    ans[id]+=tmp;
                }
                else{
                    ans[id]-=tmp;
                }
            }
        }
    }

    for(int i=1;i<=MAXM;i++){
        numlesscnt[i]=0;
        nummoresum[i]=0;
    }
    for(int i=1;i<=bnum;i++){
        blocklesscnt[i]=0;
        blockmoresum[i]=0;
    }
    for(int x=n;x>=1;x--){
        addval(val[x]);
        for(int i=headqr[x];i;i=nxtq[i]){
            int l=ql[i],r=qr[i],op=qop[i],id=qid[i];
            for(int j=l;j<=r;j++){
                tmp=1ll*lesscnt(val[j])*val[j]+moresum(val[j]);
                if(op==1){
                    ans[id]+=tmp;
                }
                else{
                    ans[id]-=tmp;
                }
            }
        }
    }
}

int main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++){
        val[i]=read();
    }
    for(int i=1;i<=m;i++){
        nums[i].l=read(),nums[i].r=read();
        nums[i].id=i;
    }
    prepare();
    compute();
    for(int i=2;i<=m;i++){
        ans[nums[i].id]+=ans[nums[i-1].id];
    }
    for(int i=1;i<=m;i++){
        ans[nums[i].id]+=presum[nums[i].r]-presum[nums[i].l-1];
    }
    for(int i=1;i<=m;i++){
        printf("%lld\n",ans[i]);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXM = 4e5+8;
#define int long

auto compare = [](const pair<int, int>& left, const pair<int, int>& right) {
    return left.second > right.second; // 注意这里是大于，因为我们想要小根堆
};
priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(compare)> heap(compare);
int n,m,k,s;
int p,q;
int grade[MAXN];

int head[MAXN];
int to[MAXM];
int Next[MAXM];
int weight[MAXM];
int cnt=1;

int edge[MAXM][2];

int dis[MAXN];
bool vis[MAXN];

void add_edge(int u, int v, int w) {
    Next[cnt] = head[u];
    to[cnt] = v;
    weight[cnt] = w;
    head[u] = cnt++;
}

signed main()
{
    cin>>n>>m>>k>>s>>p>>q;
    for(int i=1;i<=n;i++){
        grade[i]=1;
        dis[i]=LONG_MAX;
    }
    for(int i=1;i<=k;i++){
        int h;
        cin>>h;
        grade[h]=3;
    }
    for(int i=1;i<=m;i++){
        int u,v;
        cin>>u>>v;
        if(grade[u]==3){
            grade[v]=grade[v]==3?3:2;
        }
        if(grade[v]==3){
            grade[u]=grade[u]==3?3:2;
        }
        edge[i][0]=u;
        edge[i][1]=v;
    }
    grade[1]=0;
    grade[n]=0;

    for(int i=1;i<=m;i++){
        int u = edge[i][0], v = edge[i][1];
        //cout<<u<<' '<<v<<endl;
        int wu = (grade[u] == 3) ? INT_MAX/2 : (grade[u] == 0 ? 0 : (grade[u] == 1 ? p : q));
        int wv = (grade[v] == 3) ? INT_MAX/2 : (grade[v] == 0 ? 0 : (grade[v] == 1 ? p : q));

        add_edge(u, v, wv); // 假设 add_edge 是一个您定义的函数，用于添加边和权重
        add_edge(v, u, wu); // 添加反向边和权重
    }
    dis[1]=0;
    heap.push({1,0});
    while(!heap.empty()){
        int u=heap.top().first;
        long w=heap.top().second;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=true;
        for(int i=head[u];i>0;i=Next[i]){
            int v=to[i];
            if(!vis[v]&&dis[v]>weight[i]+w){
                dis[v]=weight[i]+w;
                heap.push({v,dis[v]});
            }
        }
    }
