long long dfs(int x,int y,int len){
    //表示在第x行第y列长度为len的可能种类
    if(x==0){
        return 1;
    }
    int st=y-len+1;
    if(dp[x][y][len]){
        return dp[x][y][len];
    }
    long long ans=1;//表示直接结束
