{
    cin>>n>>m;
    build(1,n,1);
    for (int i = 1, op, jobl, jobr; i <= m; i++) {
        cin>>op;
        if (op == 0) {
            cin>>jobl;
            cin>>jobr;
            Update(jobl, jobr, 1, n, 1);
        } else {
            cin>>jobl;
            cin>>jobr;
            cout<<query(jobl, jobr, 1, n, 1)<<endl;
        }
    }
    return 0;
}

