#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;

int x[MAXN<<1];
int cnt=0;
struct node{
    int l,r,len;
}nums[MAXN];
int n,m;
int tot;
int tree[MAXN*8];
int lazy[MAXN*8];

bool cmp(node a,node b){
    return a.len<b.len;
}

int getrank(int val){
    int l=1,r=tot,ans=tot;
    while(l<=r){
        int mid=(l+r)/2;
        if(x[mid]>=val){
            ans=mid;
            r=mid-1;
        }
        else{
            l=mid+1;
        }
    }
    return ans;
}

void up(int i){
    tree[i]=max(tree[i<<1],tree[i<<1|1]);
}

void build(int l,int r,int i){
    if(l==r){
        return;
    }
    else{
        int mid=(l+r)/2;
        build(l,mid,i<<1);
        build(mid+1,r,i<<1|1);
        up(i);
    }
}

void downlazy(int i,int v){
    tree[i]+=v;
    lazy[i]+=v;
}

void down(int i){
    if(lazy[i]){
        downlazy(i<<1,lazy[i]);
        downlazy(i<<1|1,lazy[i]);
        lazy[i]=0;
    }
}

void add(int jobl, int jobr, int jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        downlazy(i, jobv);
    } else {
        int mid = (l + r) >> 1;
        down(i);
        if (jobl <= mid) {
            add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);//汇总修改数据
    }
}

int query(int jobl,int jobr,int l,int r,int i){
    if (jobl <= l && r <= jobr) {
        return tree[i];
    } else {
        int ans=0;
        int mid = (l + r) >> 1;
        down(i);
        if (jobl <= mid) {
            ans=max(ans,query(jobl, jobr,l, mid, i << 1));
        }
        if (jobr > mid) {
            ans=max(ans,query(jobl, jobr,mid + 1, r, i << 1 | 1));
        }
        return ans;
    }
}

