{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>teacher[i];
        allow[i][0]=(teacher[i]+1)%3;
        allow[i][1]=(teacher[i]+2)%3;

        for(int p=1;p<=n-1;p++){
            int x;
            cin>>x;
            rk[i][x]=p;
        }
    }

    cout<<compute()<<endl;

    return 0;
}

