    cin>>n>>k;
    ans=n*k;
    int l=1,r;
    while(l<=min(n,k)){
        int t=k/l;
        // r=min(n,n/t);
        r=min(k/t,n);
        ans-=t*(l+r)*(r-l+1)/2;
        l=r+1;
    }
    cout<<ans<<endl;
    return 0;
}

#include <cstdio>
#include <iostream>
using namespace std;

const int N = 100005;

inline int read()
{
	int x = 0 , f = 1;	char ch = getchar();
	while(ch < '0' || ch > '9')	{if(ch == '-')	f = -1; ch = getchar();}
	while(ch >= '0' && ch <= '9') {x = (x << 3) + (x << 1) + (ch ^ 48); ch = getchar();}
	return x * f;
}

int n , top;
int a[N] , st[N] , l[N] , r[N];
long long sum[N];
long long ans;

int main()
{
	n = read();
	for(int i = 1;i <= n;i ++)
        sum[i] = sum[i-1] + (a[i] = read());
	for(int i = 1;i <= n;i ++){
		while(top && a[st[top]] >= a[i])
            top --;
		l[i] = st[top];
		st[++top] = i;
	}
	top = 0;
	st[0] = n+1;
	for(int i = n;i >= 1;i --)
	{
		while(top && a[st[top]] >= a[i])
            top --;
		r[i] = st[top] - 1;
		st[++top] = i;
 	}
 	for(int i = 1;i <= n;i ++)
        ans = max(ans,(sum[r[i]] - sum[l[i]]) * a[i]);
 	return printf("%lld\n",ans) , 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 150005;

int n,m;

int father[MAXN];

int fa[MAXN];
int ls[MAXN];
int rs[MAXN];
int sta[MAXN];
bool rev[MAXN];

int val[MAXN];
int sum[MAXN];
int all[MAXN];

int find(int x){
    return x==father[x]?x:father[x]=find(father[x]);
}

void up(int x){
    all[x]=all[ls[x]]+all[rs[x]]+sum[x];
}

// 判断节点x是不是辅助splay的顶部节点
bool isroot(int x) {
    return ls[fa[x]] != x && rs[fa[x]] != x;
}

// x不是辅助splay的顶部节点才能调用，返回x是其父的哪侧儿子
int lr(int x) {
    return ls[fa[x]] == x ? 0 : 1;
}

// 翻转以x为根的辅助splay，交换左右儿子，打上翻转标记
void reverse(int x) {
    if (x != 0) {
        swap(ls[x], rs[x]);
        rev[x] = !rev[x];
    }
}

// 处理翻转懒更新
void down(int x) {
    if (rev[x]) {
        reverse(ls[x]);
        reverse(rs[x]);
        rev[x] = false;
    }
}

// x向上旋转
void rotate(int x) {
    int f = fa[x], g = fa[f];
    if (lr(x) == 0) {
        ls[f] = rs[x];
        if (ls[f] != 0) {
            fa[ls[f]] = f;
        }
        rs[x] = f;
    } else {
        rs[f] = ls[x];
        if (rs[f] != 0) {
            fa[rs[f]] = f;
        }
        ls[x] = f;
    }
    if (!isroot(f)) {
        if (lr(f) == 0) {
            ls[g] = x;
        } else {
            rs[g] = x;
        }
    }
    fa[f] = x;
    fa[x] = g;
    up(f);
    up(x);
}

// x提到辅助splay的顶部
void splay(int x) {
    int siz = 0;
    sta[++siz] = x;
    for (int y = x; !isroot(y); y = fa[y]) {
        sta[++siz] = fa[y];
    }
    while (siz != 0) {
        down(sta[siz--]);
    }
    while (!isroot(x)) {
        int f = fa[x];
        if (!isroot(f)) {
            if (lr(x) == lr(f)) {
                rotate(f);
            } else {
                rotate(x);
            }
        }
        rotate(x);
    }
}

// 打通当前原树根到x的路径，使其成为一条实链
// 可以认为这个函数就是最关键的函数
void access(int x) {
    x=find(x);
    for(int y=0;x!=0;y=x,x=fa[x]){
        splay(x);
        rs[x]=y;
        up(x);
        fa[x]=find(fa[x]);
    }
}

// 让x变成原树的根，不改变连通方式
// 这个主要是为了access服务,因为access需要的是树根节点
void makeroot(int x) {
    // 保证x和树根在同一个实链上，也就是同一个辅助splay树
    access(x);
    // 提根x
    splay(x);
    // 因为此时x已经是根节点，所以相当于是最顶层了
    // 翻转左右节点
    reverse(x);
}

int findroot(int x) {
    access(x);
    splay(x);
    down(x);
    while (ls[x] != 0) {
        x = ls[x];
        down(x);
    }
    splay(x);
    return x;
}

void split(int x, int y) {
    makeroot(x);
    access(y);
    splay(y);
}

void condense(int x, int root) {
    if (x != 0) {
        father[x] = root;
        sum[root] += sum[x];
        condense(ls[x], root);
        condense(rs[x], root);
    }
}

void link(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y){
        return ;
    }
    makeroot(x);
    if(findroot(y)!=x){
        fa[x]=y;
    }
    else{
        condense(rs[x],x);
        rs[x]=0;
        up(x);
    }
}

void update(int x,int y){
    int delta=y-val[x];
    val[x]=y;
    x=find(x);
    makeroot(x);
    sum[x]+=delta;
    up(x);
}

int query(int x,int y){
    x = find(x);
    y = find(y);
    if (findroot(x) != findroot(y)) {
        return -1;
    }
    split(x, y);
    return all[y];
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=n;i++){
        cin>>val[i];
        father[i]=i;
        sum[i]=val[i];
        all[i]=val[i];
    }

    for(int i=1;i<=m;i++){
        int op,x,y;
        cin>>op>>x>>y;
        if(op==1){
            link(x,y);
        }
        else if(op==2){
            update(x,y);
        }
        else{
            cout<<query(x,y)<<endl;
        }
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e5+5;
const int MAXH = 22;

int n,m,p;

struct Edge{
    int u,v;
};
Edge edge[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cnt=1;

bool vis[MAXN];

int dep[MAXN];
int st[MAXN][MAXH];
int fa[MAXN];
int edgeid[MAXN];
int ans[MAXN];

int node[MAXN];
int nodecnt;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

inline void addedge(int u,int v,int w){
    nxt[cnt]=head[u];
    to[cnt]=v;
    weight[cnt]=w;
    head[u]=cnt++;
}

void dfs(int u,int fa){
    dep[u]=dep[fa]+1;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        edgeid[v]=weight[i];
        dfs(v,u);
    }
}

inline int lca(int x,int y){
    if(dep[x]<dep[y]){
        swap(x,y);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[x][i]]>=dep[y]){
            x=st[x][i];
        }
    }
    if(x==y){
        return x;
    }
    for(int i=p;i>=0;i--){
        if(st[x][i]!=st[y][i]){
            x=st[x][i];
            y=st[y][i];
        }
    }
    return st[x][0];
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx!=fy){
        if(dep[fx]>dep[fy]){
            swap(fx,fy);
        }
        fa[fy]=fx;
    }
}

void compute(int now,int goal){
    now=find(now);
    while(dep[now]>dep[goal]){
        node[++nodecnt]=edgeid[now];
        un(now,st[now][0]);
        now=find(st[now][0]);
    }
}

int main()
{
    n=read(),m=read();
    p=log2(n)+1;
    for(int i=1;i<=m;i++){
        edge[i].u=read();
        edge[i].v=read();
    }
    for(int i=1;i<n;i++){
        int id=read();
        vis[id]=true;
        addedge(edge[id].u,edge[id].v,id);
        addedge(edge[id].v,edge[id].u,id);
    }
    dfs(1,0);
    // for(int i=1;i<=n;i++){
    //     cout<<i<<":  "<<edgeid[i]<<endl;
    // }
    // cout<<endl;
    for(int i=1;i<=n;i++){
        fa[i]=i;
    }
    int now=0;
    for(int i=1;i<=m;i++){
        if(ans[i]){
            continue;
        }
        if(vis[i]){
            ans[i]=++now;
            un(edge[i].u,edge[i].v);
        }
        else{
            int fa=lca(edge[i].u,edge[i].v);
            // cout<<i<<":  "<<edge[i].u<<' '<<edge[i].v<<' '<<fa<<endl;
            nodecnt=0;
            compute(edge[i].u,fa);
            compute(edge[i].v,fa);

            sort(node+1,node+nodecnt+1);
            for(int k=1;k<=nodecnt;k++){
                int id=node[k];
                // cout<<' '<<id;
                if(!ans[id]){
                    ans[id]=++now;
                }
            }
            // cout<<endl;
            ans[i]=++now;
        }
    }

    for(int i=1;i<=m;i++){
        cout<<ans[i]<<' ';
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 3e5+5;
const int INF = INT_MAX;

int n,m;

struct Edge{
    int u,v,w;
    bool flag;
};
Edge edge[MAXN];

int fakruskal[MAXN];

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int weight[MAXN<<1];
int cntg=1;

int dfncnt;
int dfn[MAXN];
int sz[MAXN];
int faMST[MAXN];
int faweight[MAXN];
int dep[MAXN];

int faECC[MAXN];
int top[MAXN];
int minn[MAXN];

bool reach[MAXN];

int segf[MAXN<<2];
int lazyf[MAXN<<2];
int segans[MAXN<<2];
int lazyans[MAXN<<2];

bool cmp(Edge &a,Edge &b){
    return a.w<b.w;
}

int find(int x){
    return x==fakruskal[x]?x:fakruskal[x]=find(fakruskal[x]);
}

void addedge(int u,int v,int w){
    nxt[cntg]=head[u];
    to[cntg]=v;
    weight[cntg]=w;
    head[u]=cntg++;
}

void kruskal(){
    sort(edge+1,edge+m+1,cmp);
    for(int i=1;i<=n;i++){
        fakruskal[i]=i;
    }

    for(int i=1;i<=m;i++){
        int x=edge[i].u;
        int y=edge[i].v;
        int w=edge[i].w;
        int fx=find(x);
        int fy=find(y);
        if(fx!=fy){
            addedge(x,y,w);
            addedge(y,x,w);
            fakruskal[fx]=fy;
            edge[i].flag=true;
        }
    }
}

void dfs(int u,int f){
    faMST[u]=f;
    dfn[u]=++dfncnt;
    sz[u]=1;
    dep[u]=dep[f]+1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        int w=weight[i];
        if(v!=f){
            faweight[v]=w;
            dfs(v,u);
            sz[u]+=sz[v];
        }
    }
}

int findECC(int x){
    return faECC[x]==x?x:faECC[x]=findECC(faECC[x]);
}

void initECC(){
    for(int i=1;i<=n;i++){
        faECC[i]=i;
        top[i]=i;
        minn[i]=INF;
    }
}

void build(int l,int r,int i,int *seg,int *lazy){
    seg[i]=INF;
    lazy[i]=INF;

    if(l<r){
        int mid=(l+r)>>1;
        build(l,mid,i<<1,seg,lazy);
        build(mid+1,r,i<<1|1,seg,lazy);
    }
}

void lazy(int jobv,int i,int *seg,int *lzy){
    seg[i]=min(seg[i],jobv);
    lzy[i]=min(lzy[i],jobv);
}

void down(int i,int *seg,int *lzy){
    if(lzy[i]!=INF){
        lazy(lzy[i],i<<1,seg,lzy);
        lazy(lzy[i],i<<1|1,seg,lzy);
        lzy[i]=INF;
    }
}

// 区间取 min
void update(int jobl, int jobr, int jobv, int l, int r, int i, int *seg, int *lzy) {
    if (jobl <= l && r <= jobr) {
        lazy(jobv, i, seg, lzy);
        return;
    }

    down(i, seg, lzy);

    int mid = (l + r) >> 1;

    if (jobl <= mid) {
        update(jobl, jobr, jobv, l, mid, i << 1, seg, lzy);
    }

    if (jobr > mid) {
        update(jobl, jobr, jobv, mid + 1, r, i << 1 | 1, seg, lzy);
    }

    seg[i] = min(seg[i << 1], seg[i << 1 | 1]);
}

// 单点强制赋值
void update(int pos, int jobv, int l, int r, int i, int *seg, int *lzy) {
    if (l == r) {
        seg[i] = jobv;
        lzy[i] = INF;
        return;
    }

    down(i, seg, lzy);

    int mid = (l + r) >> 1;

    if (pos <= mid) {
        update(pos, jobv, l, mid, i << 1, seg, lzy);
    } else {
        update(pos, jobv, mid + 1, r, i << 1 | 1, seg, lzy);
    }

    seg[i] = min(seg[i << 1], seg[i << 1 | 1]);
}

// 单点查询
int query(int pos, int l, int r, int i, int *seg, int *lzy) {
    if (l == r) {
        return seg[i];
    }

    down(i, seg, lzy);

    int mid = (l + r) >> 1;

    if (pos <= mid) {
        return query(pos, l, mid, i << 1, seg, lzy);
    } else {
        return query(pos, mid + 1, r, i << 1 | 1, seg, lzy);
    }
}

void markReach(int u, int curMax) {
    if (reach[u]) return;

    reach[u] = true;

    int f = query(dfn[u], 1, n, 1, segf, lazyf);

    // f 理论上一定不是 INF；保险起见判断一下
    if (f != INF) {
        update(dfn[u], f + curMax, 1, n, 1, segans, lazyans);
    }

    for (int i = head[u]; i; i = nxt[i]) {
        int v = to[i];

        // 只往 MST 的儿子方向走
        if (faMST[v] != u) continue;

        // 当前最大边权 curMax 下，只能经过权值 <= curMax 的树边
        if (!reach[v] && weight[i] <= curMax) {
            markReach(v, curMax);
        }
    }
}

// 非树边形成环，合并 MST 上 u-v 路径
int mergePath(int u, int v, int w) {
    while (findECC(u) != findECC(v)) {
        int ru = findECC(u);
        int rv = findECC(v);

        int tu = top[ru];
        int tv = top[rv];

        // 每次合并深度更大的那个分量
        if (dep[tu] < dep[tv]) {
            swap(u, v);
            swap(ru, rv);
            swap(tu, tv);
        }

        int father = faMST[tu];
        int rf = findECC(father);

        // 当前分量向父亲分量合并
        // 新分量中的最小边权来自：
        // 1. 原 ru 分量内部 minn[ru]
        // 2. 父亲 rf 分量内部 minn[rf]
        // 3. tu 到父亲的 MST 树边 faweight[tu]
        // 4. 当前非树边 w
        minn[rf] = min(minn[rf], minn[ru]);
        minn[rf] = min(minn[rf], faweight[tu]);
        minn[rf] = min(minn[rf], w);

        faECC[ru] = rf;
    }

    int r = findECC(u);
    minn[r] = min(minn[r], w);

    return r;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin>>n>>m;
    for(int i=1;i<=m;i++){
        int u,v,w;
        cin>>u>>v>>w;
        edge[i]={u,v,w,false};
    }

    kruskal();

    faweight[1]=INF;
    dfs(1,0);

    initECC();

    build(1,n,1,segf,lazyf);
    build(1,n,1,segans,lazyans);

    reach[1] = true;

        for (int i = 1; i <= m; i++) {
        int u = edge[i].u;
        int v = edge[i].v;
        int w = edge[i].w;

        int ru = findECC(u);
        int rv = findECC(v);

        // 已经在同一个动态边双分量里，跳过
        if (ru == rv) continue;

        if (edge[i].flag) {
            // 树边：负责让新点可达
            int child;

            if (faMST[u] == v) {
                child = u;
            } else {
                child = v;
            }

            // 从 1 到 child 子树中的点都会经过这条树边
            update(dfn[child], dfn[child] + sz[child] - 1, w, 1, n, 1, segf, lazyf);

            // 如果父亲已经可达，那么 child 子树中边权 <= w 的部分也会变得可达
            if (reach[faMST[child]] && !reach[child]) {
                markReach(child, w);
            }
        } else {
            // 非树边：负责形成环，压缩边双分量
            int r = mergePath(u, v, w);
            r = findECC(r);

            int t = top[r];
            int mn = minn[r];

            // 这个环/边双分量可以让最小边权变成 mn
            update(dfn[t], dfn[t] + sz[t] - 1, mn, 1, n, 1, segf, lazyf);

            // 当前最大边权是 w，所以答案候选是 mn + w
            if (mn != INF) {
                update(dfn[t], dfn[t] + sz[t] - 1, mn + w, 1, n, 1, segans, lazyans);
            }
        }
    }

    for (int i = 2; i <= n; i++) {
        cout << query(dfn[i], 1, n, 1, segans, lazyans) << '\n';
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int INF = 1e16;
const int MAXN = 2e5+5;
const int MAXM = 1e6+5;

int n;

int degree[MAXN];
int val1[MAXN];
int val2[MAXN];

int dp[MAXN];

int dis[MAXN];
bool vis[MAXN];

int cnt=1;
int head[MAXN];
int nxt[MAXM];
int to[MAXM];

struct compare{
    bool operator()(const pair<int,int>&a,const pair<int,int>&b){
        return a.second>b.second;
    }
};
priority_queue<pair<int,int>,vector<pair<int,int>>,compare>heap;

inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){
        if(ch=='-')
            f=-1;
        ch=getchar();
    }
    while(ch>='0' && ch<='9')
        x=x*10+ch-'0',ch=getchar();
    return x*f;
}

void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

signed main()
{
    n=read();
    for(int i=1;i<=n;i++){
        val1[i]=read(),val2[i]=read();
        heap.push({i,val2[i]});
        degree[i]=read();
        for(int j=1;j<=degree[i];j++){
            int u=read();
            addedge(u,i);
        }
    }
    while(!heap.empty()){
        int u=heap.top().first;
        if(!dp[u])
            dp[u]=heap.top().second;
        heap.pop();
        if(vis[u]){
            continue;
        }
        vis[u]=1;
        for(int i=head[u];i;i=nxt[i]){
            int v=to[i];
            if(vis[v]){
                continue;
            }
            dis[v]+=dp[u];
            degree[v]--;
            if(degree[v]==0){
                heap.push({v,dis[v]+val1[v]});
            }
        }
    }
    cout<<dp[1]<<endl;
    return 0;
}

