        }
    }
    for(int i=arr[1];i<=m;i++){
        f[1][i]=(i-arr[1])*(i-arr[1]);
    }
    for(int i=2;i<=n;i++){
        int k=1e9;
        for(int j=arr[i-1];j<=m;j++){
            k=min(k,f[i-1][j]-j*c);
            if(j>=arr[i]){
                f[i][j]=k+(j-arr[i])*(j-arr[i])+c*j;
            }
        }
        k=1e9;
        for(int j=m;j>=arr[i];j--){
            k=min(k,f[i-1][j]+j*c);
            f[i][j]=min(f[i][j],k-c*j+(j-arr[i])*(j-arr[i]));
        }
    }
    int ans=1e9;
    for(int i=arr[n];i<=m;i++){
        ans=min(ans,f[n][i]);
    }
    cout<<ans<<endl;
    return 0;
}

