void up(int i){
    sz[i]=sz[ls[i]]+sz[rs[i]]+1;
    for(int k=1;k<=m;k++){
        sum[i][k]=sum[ls[i]][k]+sum[rs[i]][k]+val[i][k];
    }
}

int newnode(){
    ++cnt;
    sz[cnt]=1;
    priority[cnt]=(double)rand()/RAND_MAX;
    for(int i=1;i<=m;i++){
        val[cnt][i]=key[i];
        sum[cnt][i]=key[i];
    }
    return cnt;
}

void split(int l, int r, int i, int rank) {
    if (i == 0) {
        rs[l] = ls[r] = 0;
    } else {
        if (sz[ls[i]] + 1 <= rank) {
            rs[l] = i;
            split(i, r, rs[i], rank - sz[ls[i]] - 1);
        } else {
            ls[r] = i;
            split(l, i, ls[i], rank);
        }
        up(i);
    }
}

int merge(int l, int r) {
    if (l == 0 || r == 0) {
        return l + r;
    }
    if (priority[l] >= priority[r]) {
        rs[l] = merge(rs[l], r);
        up(l);
        return l;
    } else {
        ls[r] = merge(l, ls[r]);
        up(r);
        return r;
    }
}

