            limit[i][j]=c-'0';
        }
    }

    if(white1!=white2){
        cout<<-1<<endl;
        return 0;
    }

    s=2*n*m+1,t=s+1;

    int flow=0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            if(start[i][j]&&!over[i][j]){
                addedge(s,id(i,j),1,0);
                flow++;
            }
            if(over[i][j]&&!start[i][j]){
                addedge(id(i,j)+n*m,t,1,0);
            }

            int f=limit[i][j]/2;
            if((limit[i][j]%2)&&(start[i][j]^over[i][j])){
                f++;
            }
            addedge(id(i,j),id(i,j)+n*m,f,0);

            for(int k=0;k<8;k++){
                int x=i+walk[k][0];
                int y=j+walk[k][1];
                if(x>=1&&x<=n&&y>=1&&y<=m){
                    addedge(id(i,j)+n*m,id(x,y),INF,1);
                }
            }
        }
    }

    mincostmaxflow();

    if(maxflow!=flow){
        cout<<-1<<endl;
    }
