        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs1(v,u);
    }
}

int get(int u,int ancestor){
    if(u==ancestor){
        return -1;
    }
    for(int i=p;i>=0;i--){
        if(dep[st[u][i]]>dep[ancestor]){
            u=st[u][i];
        }
    }
    return u;
}

void dfs2(int u,int fa){
    val[u]+=val[fa];
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v==fa){
            continue;
        }
        dfs2(v,u);
    }
}

inline int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

