void build(string s)//将字符串s加入字典树
{
	int l=s.size();//获取s的长度
	int now=1;//now指针设为1
	for(int i=0;i<l;++i)
	{
		if(tree[now].vis[s[i]-'a']==0)//没有建边
			tree[now].vis[s[i]-'a']=++cnt;
		now=tree[now].vis[s[i]-'a'];//跳转
	}
	tree[now].end+=1;//结尾处加上1
}
