int mu[MAXN];
int cnt;
bool vis[MAXN];
int prime[MAXN];

int primecnt[MAXN];  // 最小质因子的指数
int primesum[MAXN];  // 最小质因子的等比数列和
int sigma[MAXN];     // 约数之和

struct QUERY{
    int n,m,a,id;
};
QUERY query[MAXM];
