    int cnt=0,sum=0;
    for(int i=1;i<=n;i++){
        while(!heap.empty()&&!vis[heap.top().second]){
            heap.pop();
        }
        if(vis[val[i]]){
            heap.push({nxt[i],val[i]});
        }
        else{
            ++cnt;
            vis[val[i]]=true;
            if(sum>=q){
