// 边权上限内第k大点权，C++版
// 图里有n个点，m条无向边，点有点权，边有边权，图里可能有若干个连通的部分
// 一共有q条查询，查询格式如下
// 查询 u x k : 从点u开始，只能走过权值<=x的边
//              所有能到达的点中，打印第k大点权，如果不存在打印-1
// 1 <= n <= 10^5
// 0 <= m、q <= 5 * 10^5
// 1 <= 点权、边权 <= 10^9
// 本题要求强制在线，具体规定请打开测试链接查看
// 测试链接 : https://www.luogu.com.cn/problem/P7834
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例
#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100001;
const int MAXK = 200001;
const int MAXM = 500001;
const int MAXT = MAXN * 40;
const int MAXH = 20;

struct Edge {
    int u, v, w;
};

bool cmp(Edge x, Edge y) {
    return x.w < y.w;
}

int n, m, q, s;
int node[MAXN];
int sorted[MAXN];
Edge edge[MAXM];

// 并查集
int father[MAXK];

// Kruskal重构树
int head[MAXK];
int nxt[MAXK];
int to[MAXK];
int cntg;
int nodeKey[MAXK];
int cntu;

// 倍增表
int stjump[MAXK][MAXH];
// 子树上的叶节点个数
int leafsiz[MAXK];
// 子树上叶节点的dfn序号最小值
int leafDfnMin[MAXK];
// leafseg[i] = j，表示dfn序号为i的叶节点，原始编号为j
int leafseg[MAXK];
// dfn的计数
int cntd;

// 可持久化线段树
// 线段树的下标为某个数字，所以是值域线段树
// 数值范围[l..r]上，一共有几个数字，就是numcnt的含义
int root[MAXN];
int ls[MAXT];
int rs[MAXT];
int numcnt[MAXT];
int cntt;

int kth(int num) {
    int left = 1, right = s;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (sorted[mid] == num) {
            return mid;
        } else if (sorted[mid] < num) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

void prepare() {
    for (int i = 1; i <= n; i++) {
        sorted[i] = node[i];
    }
    sort(sorted + 1, sorted + n + 1);
    s = 1;
    for (int i = 2; i <= n; i++) {
        if (sorted[s] != sorted[i]) {
            sorted[++s] = sorted[i];
        }
    }
    for (int i = 1; i <= n; i++) {
        node[i] = kth(node[i]);
    }
}

void addEdge(int u, int v) {
    nxt[++cntg] = head[u];
    to[cntg] = v;
    head[u] = cntg;
}

int find(int i) {
    if (i != father[i]) {
        father[i] = find(father[i]);
    }
    return father[i];
}

void kruskalRebuild() {
    for (int i = 1; i <= n; i++) {
        father[i] = i;
    }
    sort(edge + 1, edge + m + 1, cmp);
    cntu = n;
    for (int i = 1, fx, fy; i <= m; i++) {
        fx = find(edge[i].u);
        fy = find(edge[i].v);
        if (fx != fy) {
            father[fx] = father[fy] = ++cntu;
            father[cntu] = cntu;
            nodeKey[cntu] = edge[i].w;
            addEdge(cntu, fx);
            addEdge(cntu, fy);
        }
    }
}

void dfs(int u, int fa) {
    stjump[u][0] = fa;
    for (int p = 1; p < MAXH; p++) {
        stjump[u][p] = stjump[stjump[u][p - 1]][p - 1];
    }
    for (int e = head[u]; e > 0; e = nxt[e]) {
        dfs(to[e], u);
    }
    if (u <= n) {
        leafsiz[u] = 1;
        leafDfnMin[u] = ++cntd;
        leafseg[cntd] = u;
    } else {
        leafsiz[u] = 0;
        leafDfnMin[u] = n + 1;
    }
    for (int e = head[u]; e > 0; e = nxt[e]) {
        leafsiz[u] += leafsiz[to[e]];
        leafDfnMin[u] = min(leafDfnMin[u], leafDfnMin[to[e]]);
    }
}

// 可持久化线段树的build
int build(int l, int r) {
    int rt = ++cntt;
    numcnt[rt] = 0;
    if (l < r) {
        int mid = (l + r) / 2;
        ls[rt] = build(l, mid);
        rs[rt] = build(mid + 1, r);
    }
    return rt;
}

// 数值范围[l..r]，加了一个数字jobi，生成新版本的可持久化线段树
int insert(int jobi, int l, int r, int i) {
    int rt = ++cntt;
    ls[rt] = ls[i];
    rs[rt] = rs[i];
    numcnt[rt] = numcnt[i] + 1;
    if (l < r) {
        int mid = (l + r) / 2;
        if (jobi <= mid) {
            ls[rt] = insert(jobi, l, mid, ls[rt]);
        } else {
            rs[rt] = insert(jobi, mid + 1, r, rs[rt]);
        }
    }
    return rt;
}

// 可持久化线段树，前版本pre，后版本post，两个版本做差，得到数值范围[l..r]的词频
// 查询这个数值范围上，第jobk大的数字是什么
int query(int jobk, int l, int r, int pre, int post) {
    if (l == r) {
        return l;
    }
    int mid = (l + r) / 2;
    int rsize = numcnt[rs[post]] - numcnt[rs[pre]];
    if (rsize >= jobk) {
        return query(jobk, mid + 1, r, rs[pre], rs[post]);
    } else {
        return query(jobk - rsize, l, mid, ls[pre], ls[post]);
    }
}

int kthMax(int u, int x, int k) {
    for (int p = MAXH - 1; p >= 0; p--) {
        if (stjump[u][p] > 0 && nodeKey[stjump[u][p]] <= x) {
            u = stjump[u][p];
        }
    }
    if(leafsiz[u] < k) {
        return 0;
    }
    int idx = query(k, 1, s, root[leafDfnMin[u] - 1], root[leafDfnMin[u] + leafsiz[u] - 1]);
    return sorted[idx];
}

