#include<bits/stdc++.h>
using namespace std;
const int MAXN = 2e5+5;

int n;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cntg=1;

int dfncnt;
int dfn[MAXN];

int sz[MAXN];
int from[MAXN];
bool cycle[MAXN];

void prepare(){
    for(int i=1;i<=n;i++){
        head[i]=0;
        dfn[i]=0;
        cycle[i]=false;
    }
    cntg=1;
    dfncnt=0;
}

void addedge(int u,int v){
    nxt[cntg]=head[u];
    to[cntg]=v;
    head[u]=cntg++;
}

void dfs(int u){
    dfn[u]=++dfncnt;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(dfn[v]==0){
            from[v]=u;
            dfs(v);
        }
        else if(dfn[u]<dfn[v]){
            cycle[u]=true;
            for(int j=v;j!=u;j=from[j]){
                cycle[j]=true;
            }
        }
    }
}

void calc(int u,int fa){
    sz[u]=1;
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa&&!cycle[v]){
            calc(v,u);
            sz[u]+=sz[v];
        }
    }
}

long long compute(){
    dfs(1);
    long long ans=0;
    for(int i=1;i<=n;i++){
        if(cycle[i]){
            calc(i,0);
            ans+=1ll*sz[i]*(sz[i]-1)/2+1ll*sz[i]*(n-sz[i]);
        }
    }
    return ans;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(0);

    int T;
    cin>>T;
    while(T--){
        cin>>n;
        prepare();
        for(int i=1;i<=n;i++){
            int u,v;
            cin>>u>>v;
            addedge(u,v);
            addedge(v,u);
        }
        cout<<compute()<<endl;
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MOD = 10007;

int n;
int fun[200][200];
int fac[MOD],inv[MOD];

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%MOD;
        }
        a=(a*a)%MOD;
        b>>=1;
    }
    return ans;
}

void build(){
    fac[0]=inv[0]=1;
    for(int i=1;i<MOD;i++){
        fac[i]=(fac[i-1]*i)%MOD;
    }
    inv[MOD-1]=power(fac[MOD-1],MOD-2);
    for(int i=MOD-2;i>=1;i--){
        inv[i]=(inv[i+1]*(i+1))%MOD;
    }
}

int comb(int a,int b){
    // cout<<999<<' '<<a<<' '<<b<<endl;
    if(b>a){
        return 0;
    }
    return ((fac[a]*inv[b]%MOD)*inv[a-b]%MOD+MOD)%MOD;
}

int lucas(int n,int m){
    if(m==0){
        return 1;
    }
    if(n<200&&m<200){
        if(fun[n][m]!=-1){
            return fun[n][m];
        }
    }
    int k=((lucas(n/MOD,m/MOD)*comb(n%MOD,m%MOD))%MOD+MOD)%MOD;
    if(n<200&&m<200){
        fun[n][m]=k;
    }
    return k;
}

signed main()
{
    cin>>n;
    if(n==0){
        cout<<0<<endl;
        return 0;
    }
    if(n==1){
        cout<<1<<endl;
        return 0;
    }
    build();
    for(int i=0;i<200;i++){
        for(int j=0;j<200;j++){
            fun[i][j]=-1;
        }
    }
    int ans=0;
    if(n%2==1){
        ans+=(n%MOD*lucas(n-1,(n-1)/2));
    }
    else{
        ans+=((2*n-1)%MOD*lucas(n-1,(n-1)/2));
    }
    int k=3;
    for(int i=0;i<=(n-1)/2-1;i++){
        ans+=lucas(n-1,i)*k%MOD;
        k+=4;
        k%=MOD;
    }
    ans=(ans%MOD+MOD)%MOD;
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 5e5+5;
const int MAXH = 22;

int n,p;
char s[MAXN];
int st[MAXN][MAXH];

int fa[MAXN];
int sz[MAXN];
vector<int>block[MAXN];

int dep[MAXN];
int dfn[MAXN];
int dfncnt;

int head[MAXN];
int nxt[MAXN<<1];
int to[MAXN<<1];
int cnt=1;

int sta[MAXN];
int top;
int match[MAXN];

inline void addedge(int u,int v){
    nxt[cnt]=head[u];
    to[cnt]=v;
    head[u]=cnt++;
}

int lca(int a,int b){
    if(dep[a]<dep[b]){
        swap(a,b);
    }
    for(int i=p;i>=0;i--){
        if(dep[st[a][i]]>=dep[b]){
            a=st[a][i];
        }
    }
    if(a==b){
        return a;
    }
    for(int i=p;i>=0;i--){
        if(st[a][i]!=st[b][i]){
            a=st[a][i];
            b=st[b][i];
        }
    }
    return st[a][0];
}

int find(int x){
    return x==fa[x]?x:fa[x]=find(fa[x]);
}

void un(int x,int y){
    int fx=find(x);
    int fy=find(y);
    if(fx==fy){
        return ;
    }
    if(sz[fx]<sz[fy]){
        swap(fx,fy);
    }
    fa[fy]=fx;
    sz[fx]+=sz[fy];
    for(int i=0;i<sz[fy];i++){
        block[fx].push_back(block[fy][i]);
    }
}

void dfs1(int u,int fa){
    if(s[u]=='('){
        sta[++top]=u;
    }
    else{
        if(top){
            match[u]=sta[top--];
        }
        else{
            match[u]=-1;
        }
    }

    dep[u]=dep[fa]+1;
    dfn[u]=++dfncnt;
    st[u][0]=fa;
    for(int i=1;i<=p;i++){
        st[u][i]=st[st[u][i-1]][i-1];
    }

    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs1(v,u);
        }
    }

    if(s[u]=='('){
        top--;
    }
    else if(match[u]>0){
        sta[++top]=match[u];
    }
}

int dist(int x,int y){
    return dep[x]+dep[y]-2*dep[lca(x,y)];
}

void dfs2(int u,int fa){
    for(int i=head[u];i;i=nxt[i]){
        int v=to[i];
        if(v!=fa){
            dfs2(v,u);
        }
    }

    int m=match[u];
    if(m<=0){
        return ;
    }

    un(m,u);
    if(st[m][0]>0&&match[st[m][0]]>0){
        un(st[m][0],m);
    }
}

bool cmp(int a,int b){
    return dfn[a]<dfn[b];
}

int main()
{
    scanf("%d",&n);
    p=log2(n)+1;
    scanf("%s",s+1);
    for(int i=1;i<n;i++){
        int u,v;
        scanf("%d %d",&u,&v);
        addedge(u,v);
        addedge(v,u);
    }
    for(int i=1;i<=n;i++){
        fa[i]=i;
        sz[i]=1;
        block[i].push_back(i);
    }
    dfs1(1,0);
    dfs2(1,0);
    int ans=0;
    for(int i=1;i<=n;i++){
        if(i!=find(i)){
            continue;
        }
        sort(block[i].begin(),block[i].end(),cmp);
        int total=0;
        int sz=block[i].size();
        for(int j=0;j<sz;j++){
            int x=block[i][j];
            int y=block[i][(j+1)%sz];
            total+=dist(x,y);
        }
        ans=max(ans,total/2+1);
    }
    if(ans<2){
        ans=0;
    }
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
