#include <cstdio>
using namespace std;

const int MAXN = 100001;

double arr[MAXN];
double sum1[MAXN << 2];
double sum2[MAXN << 2];
double addv[MAXN << 2];

void up(int i) {
    sum1[i] = sum1[i << 1] + sum1[i << 1 | 1];
    sum2[i] = sum2[i << 1] + sum2[i << 1 | 1];
}

void lazy(int i, double v, int n) {
    sum2[i] += sum1[i] * v * 2 + v * v * n;
    sum1[i] += v * n;
    addv[i] += v;
}

void down(int i, int ln, int rn) {
    if (addv[i] != 0) {
        lazy(i << 1, addv[i], ln);
        lazy(i << 1 | 1, addv[i], rn);
        addv[i] = 0;
    }
}

void build(int l, int r, int i) {
    if (l == r) {
        sum1[i] = arr[l];
        sum2[i] = arr[l] * arr[l];
    } else {
        int mid = (l + r) >> 1;
        build(l, mid, i << 1);
        build(mid + 1, r, i << 1 | 1);
        up(i);
    }
    addv[i] = 0;
}

void add(int jobl, int jobr, double jobv, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        lazy(i, jobv, r - l + 1);
    } else {
        int mid = (l + r) >> 1;
        down(i, mid - l + 1, r - mid);
        if (jobl <= mid) {
            add(jobl, jobr, jobv, l, mid, i << 1);
        }
        if (jobr > mid) {
            add(jobl, jobr, jobv, mid + 1, r, i << 1 | 1);
        }
        up(i);
    }
}

double query(double *sum, int jobl, int jobr, int l, int r, int i) {
    if (jobl <= l && r <= jobr) {
        return sum[i];
    }
    int mid = (l + r) >> 1;
    down(i, mid - l + 1, r - mid);
    double ans = 0;
    if (jobl <= mid) {
        ans += query(sum, jobl, jobr, l, mid, i << 1);
    }
    if (jobr > mid) {
        ans += query(sum, jobl, jobr, mid + 1, r, i << 1 | 1);
    }
    return ans;
}

