            int cost=(c[i]*(a[i]+j)*(a[i]+j)+d[i]*(b[i]+add[i]-j)*(b[i]+add[i]-j))-(c[i]*(a[i]+j-1)*(a[i]+j-1)+d[i]*(b[i]+add[i]-j+1)*(b[i]+add[i]-j+1));
            addedge(i,t,1,cost);
