    cin>>n;
    for(int i=1;i<=n;i++){
        char a,b,c;
        cin>>a>>b>>c;
        change[b-'A'][c-'A']|=(1<<(a-'A'));
    }
    cin>>m;
    while(m--){
        string str;
        cin>>str;
        int len=str.size();
        str=' '+str;
        for(int i=0;i<=len;i++){
            for(int j=0;j<=len;j++){
                f[i][j]=0;
                dp[i][j]=INF;
            }
        }
        for(int i=1;i<=len;i++){
            f[i][i]|=(1<<(str[i]-'A'));
        }
        for(int l=2;l<=len;l++){
            for(int i=1;i<=len-l+1;i++){
                int j=i+l-1;
                for(int k=i;k<j;k++){
                    for(int a=0;a<26;a++){
                        if(f[i][k]&(1<<a)){
                            for(int b=0;b<26;b++){
                                if(f[k+1][j]&(1<<b)){
                                    f[i][j]|=change[a][b];
                                }
                            }
                        }
                    }
                }
            }
        }

        for(int l=1;l<=len;l++){
            for(int i=1;i<=len-l+1;i++){
