struct node{
    int x,dis;
};
struct compare{
    bool operator()(const node&a,const node&b){
        return a.dis>b.dis;
    }
};
priority_queue<node,vector<node>,compare>heap;

// bool intree[MAXN];

// 生成树建图
int headq[MAXN];
