{
    lg2[0]=-1;
    for(int i=1;i<=30005;i++){
        lg2[i]=lg2[i>>1]+1;
    }
    int T;
    scanf("%d",&T);
    while(T--){
        scanf("%s",str+1);
        n=strlen(str+1);
        compute();
