#include<bits/stdc++.h>
using namespace std;
#define int long long
const int MAXN = 1e6+5;
const int MOD = 104857601;

int n;
int phi[MAXN];
int prime[MAXN];
int cnt=0;
bool vis[MAXN];

void euler(int n){
    phi[1]=1;
    for(int i=2;i<=n;i++){
        if(!vis[i]){
            prime[++cnt]=i;
            phi[i]=i-1;
        }
        for(int j=1;j<=cnt&&i*prime[j]<=n;j++){
            vis[i*prime[j]]=1;
            if(i%prime[j]==0){
                phi[i*prime[j]]=prime[j]*phi[i];
                break;
            }
            else{
                phi[i*prime[j]]=(prime[j]-1)*phi[i];
            }
        }
    }
    for(int i=1;i<=n;i++){
        phi[i]=(phi[i-1]+phi[i])%(MOD-1);
    }
}

int power(int a,int b){
    int ans=1;
    while(b){
        if(b&1){
            ans=(ans*a)%MOD;
        }
        b>>=1;
        a=(a*a)%MOD;
    }
    return ans;
}

signed main()
{
    cin>>n;
    euler(n);
    // for(int i=1;i<=n;i++){
    //     cout<<phi[i]<<' ';
    // }
    // cout<<endl<<endl;
    int P=1;
    for(int d=1;d<=n;d++){
        int k=n/d;
        int p=(2*phi[k]-1+MOD-1)%(MOD-1);
        P=(P*power(d,p))%MOD;
    }
    int N=1;
    for(int i=1;i<=n;i++){
        N=(N*i)%MOD;
    }
    N=power(N,2*n%(MOD-1));
    int ans=N*power(P,MOD-3)%MOD;
    cout<<ans<<endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const double sml = 1e-6;

int n,k,low,high;
int arr[50005];
int maxq[50005],minq[50005];

bool check(double x){
	double c[50005];
	int he=1,ta=0,q[50005];
	memset(q,0,sizeof(q));
	for(int i=1;i<=n;i++)
        c[i]=arr[i]-x*(double)i;
	for(int i=low;i<=n;i++){
		while(he<=ta&&i-q[he]>=high)
            he++;
		while(he<=ta&&c[i-low+1]<=c[q[ta]])
            ta--;
		q[++ta]=i-low+1;
		if(c[i]-c[q[he]]>=x*k)
            return 1;
	}
	he=1;
	ta=0;
	memset(q,0,sizeof(q));
	for(int i=1;i<=n;i++)
        c[i]=arr[i]+x*(double)i;
	for(int i=low;i<=n;i++){
		while(he<=ta&&i-q[he]>=high)
            he++;
		while(he<=ta&&c[i-low+1]>=c[q[ta]])
            ta--;
		q[++ta]=i-low+1;
		if(c[q[he]]-c[i]>=x*k)
            return 1;
	}
	return 0;
}

int main()
{
    int test;
    cin>>test;
    while(test--){
        double ans=0;
        cin>>n>>k>>low>>high;
        for(int i=1;i<=n;i++){
            cin>>arr[i];
        }
        int h1=0,t1=0,h2=0,t2=0;;
        for(int i=1;i<=n;i++){
            while(h1<t1&&maxq[h1]+low<=i){
                h1++;
            }
            while(h1<t1&&arr[maxq[t1-1]]<arr[i]){
                t1--;
            }//h<t  保证了如果队列已经是空的  那么不在t--
            maxq[t1]=i;
            t1++;
            while(h2<t2&&minq[h2]+low<=i){
                h2++;
            }
            while(h2<t2&&arr[minq[t2-1]]>arr[i]){
                t2--;
            }//h<t  保证了如果队列已经是空的  那么不在t--
            minq[t2]=i;
            t2++;
            ans=max(ans,(arr[maxq[h1]]-arr[minq[h2]])*1.0/(low-1+k));
        }
        //cout<<ans<<endl;
        double l=0,r=1e3,mid;
        while(r-l>=sml&&l<r){
            mid=(l+r)/2.0;
            if(check(mid))
                l=mid;
            else
                r=mid;
        }
        ans=max(ans,mid);
        printf("%.4lf\n",ans);
    }
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int INF = 1e9;

int n;

int dp[MAXN];
char s[MAXN];

int tree[MAXN][4];
int len[MAXN];
int fail[MAXN];
int fa[MAXN];
int half[MAXN];
int cnt;
int last;

void init(){
    cnt=1;
    last=0;
    len[0]=0,len[1]=-1;
    fail[0]=1;//偶根节点的fail指针指向奇根
    fail[1]=1;
    s[0]='#';// 特殊字符，防止越界
    half[0]=0,half[1]=1;
}

// 在fail链上查找满足条件的节点  即回文串前面一个字母是t[i]的位置  最大的位置
int getfail(int p,int i){
    while(s[i-len[p]-1]!=s[i]){
        p=fail[p];
    }
    return p;
}

// 添加字符t[i]到回文自动机
void insert(int i){
    int c;
    if(s[i]=='A'){
        c=0;
    }
    else if(s[i]=='T'){
        c=1;
    }
    else if(s[i]=='G'){
        c=2;
    }
    else{
        c=3;
    }
    // 查找合适的节点  其实这里找的是一个类似于父亲节点
    int cur=getfail(last,i);

    // 如果该节点不存在，创建新节点
    if(!tree[cur][c]){
        int x=++cnt;
        len[x]=len[cur]+2;

        int p=getfail(fail[cur],i);
        fail[x]=tree[p][c];

        if(len[x]<=1){
            half[x]=0;
        }
        else{
            int v=half[cur];
            while(len[v]+2>len[x]/2||s[i-len[v]-2]!=s[i]){
                v=fail[v];
            }
            half[x]=tree[x][c];
        }

        tree[cur][c]=x;
        fa[x]=cur;
    }
    last=tree[cur][c];
}

void compute(){
    for(int i=1;i<=cnt;i++){
        dp[i]=INF;
    }
    dp[0]=0;
    for(int i=0;i<3;i++){
        dp[tree[0][i]]=2;
    }
    for(int i=2;i<=cnt;i++){
        if(len[i]%2==1||len[i]<=2){
            continue;
        }
        if(len[fa[i]]%2==0){
            dp[i]=min(dp[i],dp[fa[i]]+1);
        }
        if(len[half[i]]%2==0){
            dp[i]=min(dp[i],dp[half[i]]+len[i]/2-len[half[i]]+1);
        }
    }
}

int main()
{
    int T;
    scanf("%d",&T);
    while(T--){
        scanf("%s",s+1);
        init();
        n=strlen(s+1);
        for(int i=1;i<=n;i++){
            insert(i);
        }
        compute();
        int ans=INF;
        for(int i=1;i<=cnt;i++){
            if(len[i]%2==0){
                ans=min(ans,n-len[i]+dp[i]);
            }
        }
        cout<<ans<<endl;
    }
    return 0;
}

// 同谋者，C++版
// 一共n个人，编号1~n，分配每个人进入交流队或者保密队中的一个
// 交流队要求内部任意两人都认识，保密队要求内部任意两人都不认识
// 给定每人的认识列表，如果x的认识列表里有y，那么y的认识列表里有x
// 分配还要求交流队和保密队都不能为空，计算n个人分成两组的方法数
// 如果不存在任何方法，打印0
// 2 <= n <= 5000
// 所有认识列表的总人数 <= n * (n - 1)
// 测试链接 : https://www.luogu.com.cn/problem/P3513
// 测试链接 : https://loj.ac/p/2155
// 如下实现是C++的版本，C++版本和java版本逻辑完全一样
// 提交如下代码，可以通过所有测试用例

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 5001;
const int MAXT = MAXN << 1;
const int MAXM = MAXN * MAXN;
int n, k, x;
bool know[MAXN][MAXN];

int head[MAXT];
int nxt[MAXM];
int to[MAXM];
int cntg;

int dfn[MAXT];
int low[MAXT];
int cntd;

int sta[MAXT];
int top;

int belong[MAXT];
int sccCnt;

int team1[MAXN];
int team2[MAXN];
int cnt1, cnt2;

int other[MAXN];

void addEdge(int u, int v) {
   nxt[++cntg] = head[u];
   to[cntg] = v;
   head[u] = cntg;
}

void tarjan(int u) {
   dfn[u] = low[u] = ++cntd;
   sta[++top] = u;
   for (int e = head[u]; e > 0; e = nxt[e]) {
       int v = to[e];
       if (dfn[v] == 0) {
           tarjan(v);
           low[u] = min(low[u], low[v]);
       } else {
           if (belong[v] == 0) {
               low[u] = min(low[u], dfn[v]);
           }
       }
   }
   if (dfn[u] == low[u]) {
       sccCnt++;
       int pop;
       do {
           pop = sta[top--];
           belong[pop] = sccCnt;
       } while (pop != u);
   }
}

int compute() {
   for (int i = 1; i <= n; i++) {
       if (belong[i] == belong[i + n]) {
           return 0;
       }
   }
   for (int i = 1; i <= n; i++) {
       if (belong[i] < belong[i + n]) {
           team1[++cnt1] = i;
       } else {
           team2[++cnt2] = i;
       }
   }
   int ans = cnt1 > 0 && cnt2 > 0 ? 1 : 0;
   for (int i = 1, a, b; i <= cnt1; i++) {
       a = team1[i];
       for (int j = 1; j <= cnt2; j++) {
           b = team2[j];
           if (know[a][b]) {
               other[a] = other[a] == 0 ? b : -1;
           } else {
               other[b] = other[b] == 0 ? a : -1;
           }
       }
   }
   if (cnt1 > 1) {
       for (int i = 1; i <= cnt1; i++) {
           if (other[team1[i]] == 0) {
               ans++;
           }
       }
   }
   if (cnt2 > 1) {
       for (int i = 1; i <= cnt2; i++) {
           if (other[team2[i]] == 0) {
               ans++;
           }
       }
   }
   for (int i = 1, a, b; i <= cnt1; i++) {
       a = team1[i];
       for (int j = 1; j <= cnt2; j++) {
           b = team2[j];
           if (know[a][b]) {
               if (other[a] == b && other[b] == 0) {
                   ans++;
               }
           } else {
               if (other[b] == a && other[a] == 0) {
                   ans++;
               }
           }
       }
   }
   return ans;
}

int main() {
   ios::sync_with_stdio(false);
   cin.tie(nullptr);
   cin >> n;
   for (int i = 1; i <= n; i++) {
       cin >> k;
       for (int j = 1; j <= k; j++) {
           cin >> x;
           know[i][x] = true;
       }
   }
   for (int i = 1; i <= n; i++) {
       for (int j = i + 1; j <= n; j++) {
           if (know[i][j]) {
               addEdge(i + n, j);
               addEdge(j + n, i);
           } else {
               addEdge(i, j + n);
               addEdge(j, i + n);
           }
       }
   }
   for (int i = 1; i <= n << 1; i++) {
       if (dfn[i] == 0) {
           tarjan(i);
       }
   }
   int ans = compute();
   cout << ans << "\n";
   return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int MAXN = 1e5+5;
const int MAXH = 17;

int q,n;
int dep[MAXN];
int st[MAXN][MAXH];
int u[MAXN],v[MAXN];//直径端点
int fa[MAXN];//集合代表点

inline int lca(int u,int v){
    if(dep[u] < dep[v]) swap(u,v);
    for(int i=MAXH-1;i>=0;i--)
        if(dep[st[u][i]] >= dep[v]) u = st[u][i];
    if(u == v) return u;
    for(int i=MAXH-1;i>=0;i--)
        if(st[u][i] != st[v][i]) u = st[u][i], v = st[v][i];
    return st[u][0];
}

int dist(int a,int b){
    int f=lca(a,b);
    return dep[a]+dep[b]-2*dep[f];
}

int main()
{
    cin>>q;
    while(q--){
        char op;
        int p;
        cin>>op>>p;
        if(op=='B'){
            n++;
            if(p==-1){
                dep[n]=1;
                fa[n]=n;
                u[n]=n,v[n]=n;
            }
            else{
                dep[n]=dep[p]+1;
                st[n][0]=p;
                for(int i=1;i<MAXH;i++){
                    st[n][i]=st[st[n][i-1]][i-1];
                }
                fa[n]=fa[p];
                int len=dist(u[fa[n]],v[fa[n]]);
                int d1=dist(n,u[fa[n]]);
                int d2=dist(n,v[fa[n]]);
                if(d1>len&&d1>=d2){
                    v[fa[n]]=u[fa[n]];
                    u[fa[n]]=n;
                }
                else if(d2>len&&d2>=d1){
                    u[fa[n]]=v[fa[n]];
                    v[fa[n]]=n;
                }
            }
        }
        else{
            cout<<max(dist(p,u[fa[p]]),dist(p,v[fa[p]]))<<endl;
        }
    }
    return 0;
}

